// Prepare comprehensive context for Traffic AI Agent Reasoning
const complaint = $('Webhook: Receive Traffic Incident').first().json.body || {};
const trafficData = $('Google Maps / Traffic API').first().json || {};
const weatherData = $('Weather & Environmental API').first().json || {};
const routesData = $('Maps Directions API (Alternative Routes)').first().json || {};

const roadName = complaint.location?.address || trafficData.road_name || 'Major Arterial Corridor';
const currentSpeed = trafficData.current_speed_kmh || 7.0;
const typicalSpeed = trafficData.typical_speed_kmh || 45.0;
const isAccident = (complaint.description || '').toLowerCase().includes('accident') || 
                   (complaint.incident_type || '').toUpperCase() === 'ACCIDENT' ||
                   (trafficData.active_incidents && trafficData.active_incidents.length > 0);

// Determine Congestion Level
let severity = 'MODERATE';
if (currentSpeed < 10 || isAccident) {
  severity = 'SEVERE';
} else if (currentSpeed < 20) {
  severity = 'MODERATE';
} else {
  severity = 'LOW';
}

// Alternative routes from API
const alternativeRoutes = (routesData.routes || []).map(r => ({
  route_name: r.route_name,
  via_roads: r.via_roads,
  estimated_delay_mins: r.delay_mins || 2,
  capacity_status: r.traffic_condition || 'MODERATE'
}));

// AI Recommendations formulated based on live conditions
const recommendations = [
  `Deploy Traffic Police at intersections leading to ${roadName} for manual green light extension.`,
  `Broadcast dynamic VMS alert 2km prior: 'ACCIDENT/JAM ON ${roadName.toUpperCase()} - DIVERT VIA ${alternativeRoutes[0]?.route_name || 'PARALLEL BYPASS'}'`,
  `Synchronize adaptive traffic signal timer on bypass corridor to favor diverted vehicle stream.`
];

if (weatherData.weather_condition === 'RAIN') {
  recommendations.push('Wet pavement hazard: Advisory speed reduction to 30 km/h on alternative diversion.');
}

const output = {
  incident_id: 'TRF-INC-' + Date.now(),
  complaint_id: complaint.complaint_id || 'CMP-TRF-001',
  source_agent: 'traffic_management_agent',
  congestion_report: `Severe traffic bottleneck detected on ${roadName}. Current speed: ${currentSpeed} km/h (Normal: ${typicalSpeed} km/h). Delay: ~${Math.round(trafficData.delay_seconds / 60 || 24)} mins due to ${isAccident ? 'accident blockage' : 'high density volume'}.`,
  severity_level: severity,
  speed_kmh: currentSpeed,
  affected_locations: [
    {
      name: roadName,
      latitude: complaint.location?.latitude || trafficData.location?.lat || 28.5828,
      longitude: complaint.location?.longitude || trafficData.location?.lng || 77.1685,
      choke_radius_meters: severity === 'SEVERE' ? 2000 : 800
    }
  ],
  alternative_routes: alternativeRoutes,
  recommendations: recommendations,
  escalate_to_command: severity === 'SEVERE' || isAccident,
  command_alert_headline: `[TRAFFIC ALERT] Severe Congestion & Disruption on ${roadName}`
};

return output;
